<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {request,mutate,pending} from '../api';
import SourceFiles from './SourceFiles.vue';
const sourceBusy=ref(false),sourceRef=ref<InstanceType<typeof SourceFiles>|null>(null);
import {HospitalController,createHospitalState,hospitalSource,hospitalStatus,hospitalLineSource} from '../hospital-domain';
const props=defineProps<{locked?:boolean}>(),emit=defineEmits<{(e:'busy-changed',value:boolean):void;(e:'failure',value:unknown):void}>();
const state=reactive(createHospitalState()),controller=new HospitalController(request,mutate,state,e=>emit('failure',e)),sourceMode=ref<'image'|'excel'>('image'),entry=ref<'manual'|'catalog'|'source'>('manual'),keyword=ref(''),submitAcknowledged=ref(false);
const busy=computed(()=>state.loading||state.saving||sourceBusy.value),locked=computed(()=>!!props.locked||busy.value||!!pending.value),writeLocked=computed(()=>locked.value||!state.detail?.writable),navigationLocked=computed(()=>locked.value||state.dirty),pages=computed(()=>Math.max(1,Math.ceil((state.page?.total||0)/20)));
watch(()=>busy.value||state.dirty||!!pending.value,v=>emit('busy-changed',v),{immediate:true});watch(()=>state.detail?.id,()=>{submitAcknowledged.value=false;entry.value='manual';});watch(()=>state.dirty,()=>submitAcknowledged.value=false);
function choose(mode:'manual'|'catalog'|'image'|'excel'){if(writeLocked.value)return;if(mode==='image'||mode==='excel'){entry.value='source';sourceMode.value=mode;}else entry.value=mode;}
async function refresh(){if(navigationLocked.value)return;if(state.detail)await controller.open(state.detail.id);else await controller.bootstrap();}
async function reloadAfterSource(){if(state.detail&&!state.dirty)await controller.open(state.detail.id);}
async function openAfterRecovery(orderId?:string){if(orderId||state.detail?.id)await controller.open(orderId||state.detail!.id,true);else await controller.bootstrap();}
function value(e:unknown){return (e as {detail:{value:string}}).detail.value;}
function back(){if(navigationLocked.value)return;controller.close();void controller.bootstrap();}
defineExpose({refresh,openAfterRecovery,canLeave:()=>!busy.value&&!state.dirty&&!pending.value&&(sourceRef.value?.canLeave()??true)});onMounted(()=>controller.bootstrap());onBeforeUnmount(()=>{controller.dispose();emit('busy-changed',false);});
</script>
<template>
 <view class="hospital-workspace">
  <view class="heading"><text class="eyebrow">医院采购</text><text class="title">{{state.identity?.hospital.name||'我的采购需求'}}</text><text class="subtle">{{state.identity?.purchaser.name}} · 采购员</text></view>
  <view v-if="pending" class="notice">「{{pending.label}}」结果待核对。请使用页面顶部核对入口，原输入已保留。</view><view v-if="state.error" class="error">{{state.error}}</view><view v-if="state.notice" class="notice">{{state.notice}}</view><text v-if="busy" class="subtle">正在读取或提交，请稍候…</text>
  <template v-if="!state.detail"><view class="toolbar"><button class="primary" :disabled="navigationLocked" @click="controller.create()">＋ 新建采购单</button><button :disabled="navigationLocked" @click="refresh">刷新</button></view><text class="section-title">我的采购单</text><button v-for="order in state.page?.items" :key="order.id" class="order-row" :disabled="navigationLocked" @click="controller.open(order.id)"><view class="row"><text>{{order.orderNo}}</text><text class="status">{{hospitalStatus(order.status)}}</text></view><text class="subtle">{{hospitalSource(order.submissionSource)}}</text><text class="subtle">{{order.receivedDate}} · {{order.lineCount}}种明细 ›</text></button><text v-if="state.page&&!state.page.total" class="empty">还没有采购单，点击上方开始录入需求。</text><view v-if="state.page" class="pagination"><button :disabled="navigationLocked||state.page.page<=1" @click="controller.page(state.page.page-1)">上一页</button><text>{{state.page.page}} / {{pages}}</text><button :disabled="navigationLocked||state.page.page>=pages" @click="controller.page(state.page.page+1)">下一页</button></view></template>
  <template v-else>
   <view class="toolbar"><button :disabled="navigationLocked" @click="back">← 我的采购单</button><button :disabled="navigationLocked" @click="refresh">载入最新</button></view><text class="section-title">{{state.detail.orderNo}}</text><text class="subtle">{{hospitalSource(state.detail.submissionSource)}} · {{hospitalStatus(state.detail.status)}}</text>
   <view v-if="!state.detail.writable" class="notice">{{state.detail.submissionSource==='sales_entry'?'此单由销售代录，仅可查看原始需求。':'需求已提交，后续调整请联系销售。'}} </view>
   <view v-if="state.dirty" class="notice">有未保存的明细，请保存后上传原单或提交。<button :disabled="locked" @click="controller.discard()">放弃未保存修改</button></view>
   <label class="date"><text>实际接收日期</text><input :value="state.receivedDate" :disabled="writeLocked" placeholder="YYYY-MM-DD" @input="controller.editDate(value($event))"/></label>
   <template v-if="state.detail.writable"><view class="entry-grid"><button :disabled="writeLocked" @click="choose('image')">拍照 / 图片</button><button :disabled="writeLocked" @click="choose('excel')">Excel / CSV</button><button :disabled="writeLocked" @click="choose('catalog')">商品库选择</button><button :disabled="writeLocked" @click="choose('manual');controller.add()">手工添加</button></view><text class="tiny">可组合多种方式。单位固定 kg，其他单位请先人工核对并换算。</text>
    <view v-if="entry==='source'" class="source-area"><slot name="source-files" :order="state.detail" :locked="!!props.locked||state.loading||state.saving||!!pending||state.dirty||!state.detail?.writable" :mode="sourceMode" :refresh="reloadAfterSource"><SourceFiles v-if="state.detail" ref="sourceRef" :key="state.detail.id+state.detail.revisionId" :reference="{kind:'purchase_revision',orderId:state.detail.id,revisionId:state.detail.revisionId}" :mode="sourceMode" :order-version="state.detail.version" :readonly="!state.detail.writable" :locked="!!props.locked||state.loading||state.saving||!!pending||state.dirty" @busy-changed="sourceBusy=$event" @failure="emit('failure',$event)" @changed="reloadAfterSource"/></slot></view>
    <view v-if="entry==='catalog'" class="catalog"><view class="search"><input v-model="keyword" :disabled="locked" placeholder="搜索品名、别名或规格" maxlength="100"/><button :disabled="locked" @click="controller.search(keyword)">搜索</button></view><button v-for="v in state.catalog" :key="v.variantId" :disabled="writeLocked" @click="controller.add(v)">{{v.name}} · {{v.specification||'未填规格'}} ＋</button><text v-if="state.common.length" class="tiny">常用商品</text><button v-for="(v,i) in state.common" :key="'c'+i" :disabled="writeLocked" @click="controller.add(v)">{{v.name}} · {{v.spec}} ＋</button><text v-if="state.recent.length" class="tiny">最近采购</text><button v-for="(v,i) in state.recent" :key="'r'+i" :disabled="writeLocked" @click="controller.add(v)">{{v.name}} · {{v.spec}} · {{v.quantity}} kg ＋</button></view>
   </template>
   <text class="section-title">采购明细 · {{state.lines.length}} / 200</text><view v-for="(line,i) in state.lines" :key="line.id||'new-'+i" class="purchase-line"><view class="row"><text class="line-no">{{i+1}}</text><button v-if="state.detail.writable" size="mini" :disabled="writeLocked" @click="controller.remove(i)">删除</button></view><label><text>品名</text><input :value="line.name" :disabled="writeLocked" maxlength="100" placeholder="请输入原始品名" @input="controller.editLine(i,'name',value($event))"/></label><label><text>规格</text><input :value="line.spec" :disabled="writeLocked" maxlength="200" placeholder="选填" @input="controller.editLine(i,'spec',value($event))"/></label><label><text>数量 / kg</text><input :value="line.quantity" :disabled="writeLocked" type="digit" placeholder="大于0，最多两位小数" @input="controller.editLine(i,'quantity',value($event))"/></label><label><text>备注</text><input :value="line.remark" :disabled="writeLocked" maxlength="500" placeholder="选填" @input="controller.editLine(i,'remark',value($event))"/></label><text class="tiny">来源：{{hospitalLineSource(line.sourceType)}}<template v-if="line.itemId"> · 已关联标准商品</template><template v-if="line.sourceFileId"> · 含原单依据，提交前请核对原文</template></text></view>
   <text v-if="!state.lines.length" class="empty">尚无明细，请选择一种录入方式。</text>
   <view v-if="state.detail.writable" class="submit-area"><button :disabled="writeLocked||!state.dirty" @click="controller.save()">保存采购草稿</button><label class="ack"><checkbox :checked="submitAcknowledged" :disabled="writeLocked||state.dirty" @click="submitAcknowledged=!submitAcknowledged"/><text>我已核对品名、数量及kg单位；提交后交销售校对。</text></label><button class="primary" :disabled="writeLocked||state.dirty||!state.lines.length||!submitAcknowledged" @click="controller.submit()">提交采购需求</button></view>
  </template>
 </view>
</template>
<style scoped>
.hospital-workspace{padding:26rpx 0 60rpx;color:#1e3833}.heading{margin:8rpx 0 28rpx}.eyebrow,.title,.subtle,.section-title,.tiny{display:block}.eyebrow{font-size:23rpx;letter-spacing:3rpx;color:#657d76}.title{font-size:40rpx;font-weight:700;margin:12rpx 0}.subtle{font-size:25rpx;color:#65746f;line-height:1.7}.tiny{font-size:23rpx;color:#6a7d75;line-height:1.7;margin:14rpx 0}.section-title{font-size:30rpx;font-weight:650;margin:30rpx 0 18rpx}.toolbar,.row,.pagination,.search{display:flex;gap:16rpx;align-items:center}.toolbar{margin:20rpx 0}.toolbar button{flex:1}.primary{background:#1e5949!important;color:#fff!important}.order-row{width:100%;text-align:left;padding:24rpx;background:#fff;border:1rpx solid #d7e1db;margin:14rpx 0;border-radius:12rpx;line-height:1.6}.row{justify-content:space-between}.status{font-size:23rpx;color:#537164}.pagination{justify-content:center;margin-top:28rpx;font-size:24rpx}.pagination button{font-size:24rpx;margin:0}.entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:14rpx;margin-top:24rpx}.entry-grid button{font-size:25rpx;margin:0;width:100%}.purchase-line{padding:22rpx 24rpx;background:#fff;border:1rpx solid #dbe4de;border-radius:12rpx;margin:16rpx 0}.purchase-line label,.date{display:flex;gap:18rpx;align-items:center;padding:16rpx 0;border-bottom:1rpx solid #edf0eb;font-size:25rpx}.purchase-line label text,.date text{width:136rpx;flex-shrink:0}.purchase-line input,.date input{flex:1;min-width:0;font-size:26rpx}.line-no{font-weight:700;color:#3d7965}.notice,.error{padding:20rpx;background:#f5f2df;border-radius:8rpx;font-size:25rpx;line-height:1.7;margin:16rpx 0}.error{background:#fff0ec;color:#9a3f31}.notice button{margin-top:14rpx;font-size:24rpx}.empty{display:block;text-align:center;color:#75827b;padding:44rpx 10rpx;font-size:26rpx}.search input{flex:1;min-width:0;background:white;padding:18rpx;font-size:25rpx}.search button{font-size:24rpx;margin:0}.catalog{margin:20rpx 0}.catalog>button{font-size:25rpx;text-align:left;margin-top:12rpx}.ack{display:flex;align-items:center;font-size:24rpx;color:#65746f;line-height:1.7;margin:26rpx 0}.submit-area{border-top:1rpx solid #d8e3db;padding-top:26rpx;margin-top:28rpx}.submit-area>button{width:100%;font-size:27rpx}.source-area{margin:20rpx 0}
</style>
